jQuery(document).ready(function(){jQuery("#gk-whitelist-table").hide();jQuery("#gk-blacklist-table").hide()});jQuery("#gk-whitelist-title").click(function(){var b=jQuery("#gk-whitelist-table");var a=jQuery("#gk-whitelist-title.gk-section-title .gk-toggle-status");b.slideToggle(function(){if(a.attr("data-toggle-status")==="closed"){a.attr("data-toggle-status","open");a.text("-")}else{a.attr("data-toggle-status","closed");a.text("+")}})});jQuery("#gk-blacklist-title").click(function(){var b=jQuery("#gk-blacklist-table");var a=jQuery("#gk-blacklist-title.gk-section-title .gk-toggle-status");b.slideToggle(function(){if(a.attr("data-toggle-status")==="closed"){a.attr("data-toggle-status","open");a.text("-")}else{a.attr("data-toggle-status","closed");a.text("+")}})});